import re, sys, subprocess
files = subprocess.run(['grep', '-rlE', r'^class [A-Za-z_0-9]+\((.*[ ,(])?Function([,)])', 'sympy', '--include=*.py'],
                       capture_output=True, text=True, cwd='/app').stdout.split()
skip_files = {'sympy/core/function.py'}
changed = []
pat = re.compile(r'^(class [A-Za-z_0-9]+\()([^)]*)(\):)', re.M)
for f in files:
    if '/tests/' in f or f in skip_files:
        continue
    src = open('/app/' + f).read()
    n = 0
    def repl(m):
        global n
        bases = [b.strip() for b in m.group(2).split(',')]
        if 'Function' not in bases:
            return m.group(0)
        bases = ['DefinedFunction' if b == 'Function' else b for b in bases]
        n += 1
        return m.group(1) + ', '.join(bases) + m.group(3)
    new = pat.sub(repl, src)
    if n == 0:
        continue
    changed.append((f, n))
    open('/app/' + f, 'w').write(new)
for f, n in changed:
    print(n, f)
