    # c*M1*M2*...*Mk with M_i = adjoint(M_(k+1-i)) is hermitian if the
    # middle factor (for odd k) is hermitian and c is real
    from sympy.functions.elementary.complexes import adjoint
    factor, mmul = expr.as_coeff_mmul()
    mats = list(mmul.args)
    k = len(mats)
    if not all(mats[i] == adjoint(mats[k - 1 - i]) for i in range(k // 2)):
        return _matrix_herm_antiherm(expr, assumptions,
                                     Q.hermitian if herm else Q.antihermitian)
    if k % 2:
        middle = mats[k // 2]
        if ask(Q.hermitian(middle), assumptions):
