    # the matrix part is hermitian: the result depends on the coefficient
    if herm:
        if ask(Q.real(factor), assumptions):
            return True
        if ask(Q.imaginary(factor), assumptions):
            return False
    else:
        if ask(Q.imaginary(factor), assumptions):
            return True
        if ask(Q.zero(factor), assumptions):
            return True
    return None

@HermitianPredicate.register(MatMul)
def _(expr, assumptions):
    return _matmul_herm_antiherm(expr, assumptions, True)

@AntihermitianPredicate.register(MatMul)
def _(expr, assumptions):
    return _matmul_herm_antiherm(expr, assumptions, False)

@AntihermitianPredicate.register(MatrixBase)
def _(mat, assumptions):
    from sympy.core.relational import Eq
    from sympy.functions.elementary.complexes import conjugate
    from sympy.core.logic import fuzzy_bool
    if not mat.is_square:
        return False
    ret_val = True
    rows, cols = mat.shape
    for i in range(rows):
        for j in range(i, cols):
            cond = fuzzy_bool(Eq(mat[i, j], -conjugate(mat[j, i])))
            if cond is None:
                ret_val = None
            if cond == False:
                return False
    return ret_val


